    {
        bucket[i] = 0;
        i++;
    }
    for (j = 0; j < size; j++)
    {
        bucketIdx = (array[j] / exp) % radix;
        bucket[bucketIdx]++;
    }
    i = 1;
    while (i < radix)
    {
        bucket[i] += bucket[i - 1];
        i++;
    }
    out = malloc(sizeof(int) * size);
    if (!out)
    {
        free(bucket);
        return;
    }
    i = size - 1;
    while (i >= 0)
    {
        bucketIdx = (array[i] / exp) % radix;
        out[--bucket[bucketIdx]] = array[i];
        i--;
    }
